<?php
$page_title='ตัวเลือกและรูปสินค้า';require_once __DIR__.'/includes/auth_check.php';requireSeller();require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/image_upload.php';$db=(new Database())->getConnection();$seller=(int)$_SESSION['user_id'];$id=(int)($_GET['id']??$_POST['product_id']??0);$stmt=$db->prepare('SELECT * FROM products WHERE id=? AND seller_id=?');$stmt->execute([$id,$seller]);$product=$stmt->fetch();if(!$product){header('Location: '.BASE_URL.'my-store.php');exit;}$message=$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf(false);$action=$_POST['action']??'';try{if($action==='add_variant'){$sku=strtoupper(trim((string)$_POST['sku']));$name=trim((string)$_POST['name']);$price=(float)$_POST['price'];$stock=(int)$_POST['stock'];if(!preg_match('/^[A-Z0-9_-]{3,80}$/',$sku)||$name===''||$price<=0||$stock<0)throw new RuntimeException('ข้อมูล Variant ไม่ถูกต้อง');$db->prepare('INSERT INTO product_variants(product_id,sku,name,price,stock_quantity) VALUES(?,?,?,?,?)')->execute([$id,$sku,$name,$price,$stock]);$message='เพิ่มตัวเลือกสินค้าแล้ว';}elseif($action==='delete_variant'){$db->prepare('DELETE FROM product_variants WHERE id=? AND product_id=?')->execute([(int)$_POST['variant_id'],$id]);$message='ลบตัวเลือกแล้ว';}elseif($action==='add_images'){foreach($_FILES['gallery_images']['name']??[] as $i=>$unused){if(($_FILES['gallery_images']['error'][$i]??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)continue;$file=['name'=>$_FILES['gallery_images']['name'][$i],'type'=>$_FILES['gallery_images']['type'][$i],'tmp_name'=>$_FILES['gallery_images']['tmp_name'][$i],'error'=>$_FILES['gallery_images']['error'][$i],'size'=>$_FILES['gallery_images']['size'][$i]];$path=saveProductImageUpload($file);$db->prepare('INSERT INTO product_images(product_id,image_url,sort_order) VALUES(?,?,?)')->execute([$id,$path,$i]);}$message='เพิ่มรูปสินค้าแล้ว';}elseif($action==='delete_image'){$db->prepare('DELETE FROM product_images WHERE id=? AND product_id=?')->execute([(int)$_POST['image_id'],$id]);$message='ลบรูปแล้ว';}}catch(Throwable $e){$error=$e->getMessage();}}
$v=$db->prepare('SELECT * FROM product_variants WHERE product_id=? ORDER BY id');$v->execute([$id]);$variants=$v->fetchAll();$im=$db->prepare('SELECT * FROM product_images WHERE product_id=? ORDER BY sort_order,id');$im->execute([$id]);$images=$im->fetchAll();require_once __DIR__.'/includes/header.php';?>
<link rel="stylesheet" href="<?php echo BASE_URL;?>assets/css/seller.css"><div class="container" style="margin:36px auto 70px"><a href="<?php echo BASE_URL;?>my-store.php">← กลับร้านของฉัน</a><h1><?php echo e($product['name']);?></h1><?php if($message):?><p class="seller-success"><?php echo e($message);?></p><?php endif;?><?php if($error):?><p class="seller-error"><?php echo e($error);?></p><?php endif;?><div style="display:grid;grid-template-columns:1fr 1fr;gap:22px"><section class="admin-panel"><h2>Variant / SKU</h2><form method="post" class="admin-form-grid"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken());?>"><input type="hidden" name="product_id" value="<?php echo $id;?>"><input type="hidden" name="action" value="add_variant"><input name="sku" placeholder="SKU เช่น PAN-BLACK-28" required><input name="name" placeholder="สีดำ 28 ซม." required><input type="number" name="price" min="0.01" step="0.01" value="<?php echo e($product['price']);?>" required><input type="number" name="stock" min="0" value="0" required><button class="btn btn-primary">เพิ่มตัวเลือก</button></form><?php foreach($variants as $x):?><form method="post" style="display:flex;justify-content:space-between;padding:10px;border-top:1px solid var(--border-color)"><span><?php echo e($x['name'].' · '.$x['sku']);?> · <?php echo formatCurrency($x['price']);?> · <?php echo (int)$x['stock_quantity'];?> ชิ้น</span><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken());?>"><input type="hidden" name="product_id" value="<?php echo $id;?>"><input type="hidden" name="variant_id" value="<?php echo (int)$x['id'];?>"><button name="action" value="delete_variant">ลบ</button></form><?php endforeach;?></section><section class="admin-panel"><h2>รูปสินค้าเพิ่มเติม</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken());?>"><input type="hidden" name="product_id" value="<?php echo $id;?>"><input type="hidden" name="action" value="add_images"><input type="file" name="gallery_images[]" accept="image/jpeg,image/png,image/webp" multiple required><small>เลือกได้หลายรูป รูปละไม่เกิน 3 MB</small><button class="btn btn-primary">อัปโหลดรูป</button></form><div style="display:flex;flex-wrap:wrap;gap:10px;margin-top:16px"><?php foreach($images as $x):?><form method="post"><img src="<?php echo e(productImageUrl($x['image_url']));?>" alt="" style="width:100px;height:100px;object-fit:cover"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken());?>"><input type="hidden" name="product_id" value="<?php echo $id;?>"><input type="hidden" name="image_id" value="<?php echo (int)$x['id'];?>"><button name="action" value="delete_image">ลบ</button></form><?php endforeach;?></div></section></div></div><?php require_once __DIR__.'/includes/footer.php';?>
